const recordLoginFailure = `-- name: RecordLoginFailure :one
UPDATE users
SET failed_login_count = failed_login_count + 1,
    locked_until = CASE
        WHEN failed_login_count + 1 >= $1::int
        THEN now() + make_interval(secs => $2::int)
        ELSE locked_until END,
    status = CASE
        WHEN failed_login_count + 1 >= $1::int AND status = 'ACTIVE'
        THEN 'LOCKED' ELSE status END
WHERE id = $3
RETURNING failed_login_count, locked_until, status
`

type RecordLoginFailureParams struct {
	MaxFailures    int32
	LockoutSeconds int32
	ID             int64
}

type RecordLoginFailureRow struct {
	FailedLoginCount int32
	LockedUntil      *time.Time
	Status           string
}

// RecordLoginFailure increments the counter and locks the account once the
// threshold is reached. Doing both in one statement keeps the lockout decision
// atomic under concurrent guessing.
func (q *Queries) RecordLoginFailure(ctx context.Context, arg RecordLoginFailureParams) (RecordLoginFailureRow, error) {
	row := q.db.QueryRow(ctx, recordLoginFailure, arg.MaxFailures, arg.LockoutSeconds, arg.ID)
	var i RecordLoginFailureRow
	err := row.Scan(&i.FailedLoginCount, &i.LockedUntil, &i.Status)
	return i, err
}

